# Formal genotype x treatment tests, separately for G1, G3, G5.
# Input: the original untransformed integer gene counts and the RNA sample table.
# No results have been generated by this script until it is run with DESeq2.
# The design estimates effects conditional on the assigned chambers: it does
# not create independent subchamber replicates or solve batch confounding.
setwd("~/Documents/DNA_seq/RNA_seq")
COUNT_FILE <- "~/Documents/DNA_seq/RNA_seq/Count_matrix.txt"
SAMPLE_FILE <- "Metadata_Sample_Area_medians_WITH_GROUPS.csv"
OUTPUT_DIR <- "genotype_treatment_interaction_results"
RUN_OMNIBUS_LRT <- TRUE  # tests all five genotype:treatment terms jointly, per gene

if (!requireNamespace("DESeq2", quietly = TRUE)) {
  stop("Install Bioconductor package DESeq2 before running this script.")
}
dir.create(OUTPUT_DIR, showWarnings = FALSE, recursive = TRUE)

metadata <- read.csv(SAMPLE_FILE, stringsAsFactors = FALSE,
                     check.names = FALSE)
need <- c("SampleName", "Genotype", "Treatment", "Generation")
if (!all(need %in% names(metadata))) {
  stop("Sample table lacks: ", paste(setdiff(need, names(metadata)), collapse = ", "))
}
if (anyDuplicated(metadata$SampleName)) stop("SampleName must be unique.")
metadata$Generation <- as.integer(sub("^[Gg]", "", metadata$Generation))
if (anyNA(metadata$Generation) ||
    !setequal(unique(metadata$Generation), c(1L, 3L, 5L))) {
  stop("Expected G1, G3 and G5 sample labels.")
}
if (!setequal(metadata$Genotype, c("WT", "gsnor"))) {
  stop("Expected Genotype labels WT and gsnor in metadata.")
}
trt_order <- c("Control", "Drought", "CO2", "Ozone", "Heat", "Combination")
if (!setequal(metadata$Treatment, trt_order)) {
  stop("Treatment labels do not match expected treatments: ",
       paste(sort(unique(metadata$Treatment)), collapse = ", "))
}

counts <- as.matrix(read.table(COUNT_FILE, header = TRUE, row.names = 1,
                               sep = "\t", quote = "", comment.char = "",
                               check.names = FALSE))
if (anyDuplicated(rownames(counts)) || anyDuplicated(colnames(counts))) {
  stop("Duplicated gene IDs or count-matrix sample names.")
}
missing_samples <- setdiff(metadata$SampleName, colnames(counts))
if (length(missing_samples)) stop("Metadata samples missing from counts: ",
                                  paste(missing_samples, collapse = ", "))
if (!is.numeric(counts) || anyNA(counts) || any(counts < 0) ||
    any(abs(counts - round(counts)) > 1e-8)) {
  stop("Count matrix must contain raw nonnegative integer counts.")
}
storage.mode(counts) <- "integer"

# The supplied WT G1 DESeq2 script identifies these 13 WT batch-2 samples;
# all other WT G1 samples in this dataset are batch 1. The supplied mutant G1
# script does not specify comparable within-genotype batch labels. Do not
# assign the WT batch labels to mutant samples without original records.
wt_g1_batch2 <- c(
  "WT3C", "WT5C", "WT10C", "WT6D", "WT10D", "WT4CO", "WT5CO",
  "WT1O", "WT2O", "WT6H", "WT8H", "WT1T", "WT6T"
)
all_wt_g1 <- metadata$SampleName[
  metadata$Generation == 1L & metadata$Genotype == "WT"
]
if (!all(wt_g1_batch2 %in% all_wt_g1) || length(all_wt_g1) != 26L) {
  stop("WT G1 samples differ from the supplied WT G1 DESeq2 script; check batch map.")
}

as_export <- function(res) {
  data.frame(gene_id = rownames(res), as.data.frame(res),
             row.names = NULL, check.names = FALSE)
}

overview <- list()
for (g in c(1L, 3L, 5L)) {
  m <- metadata[metadata$Generation == g, , drop = FALSE]
  m$genotype <- factor(m$Genotype, levels = c("WT", "gsnor"))
  m$treatment <- factor(m$Treatment, levels = trt_order)
  m$WT_G1_batch2 <- as.integer(m$SampleName %in% wt_g1_batch2)
  rownames(m) <- m$SampleName

  tab <- table(m$genotype, m$treatment)
  if (any(tab < 2L)) stop("Too few samples in a genotype x treatment group: G", g)
  write.csv(as.data.frame(tab), file.path(OUTPUT_DIR, paste0("G", g,
    "_sample_counts.csv")), row.names = FALSE)

  # G1: adjust the documented variation between WT batch 1 and 2 with a
  # WT-specific indicator; mutant within-G1 batch details remain unavailable.
  # G3/G5: each genotype may have its own library-preparation batch; adding
  # a genotype-specific batch term is impossible when it equals genotype.
  full <- if (g == 1L) {
    ~ WT_G1_batch2 + genotype * treatment
  } else {
    ~ genotype * treatment
  }
  reduced <- if (g == 1L) {
    ~ WT_G1_batch2 + genotype + treatment
  } else {
    ~ genotype + treatment
  }

  mm <- model.matrix(full, data = m)
  if (qr(mm)$rank != ncol(mm)) {
    stop("The G", g, " design matrix is not full rank; inspect samples/batches.")
  }
  write.csv(mm, file.path(OUTPUT_DIR, paste0("G", g,
    "_design_matrix.csv")), row.names = TRUE)

  count_subset <- counts[, m$SampleName, drop = FALSE]
  stopifnot(identical(colnames(count_subset), rownames(m)))
  dds <- DESeq2::DESeqDataSetFromMatrix(
    countData = count_subset, colData = m, design = full
  )
  # Mirror the supplied G3/G5 per-contrast gene filters. Because this model
  # pools all treatments and both genotypes, some tested genes may differ
  # from the original separate-contrast gene universes.
  dds <- dds[rowSums(DESeq2::counts(dds)) > 10, ]
  dds <- DESeq2::estimateSizeFactors(dds)
  dds <- dds[rowSums(DESeq2::counts(dds, normalized = TRUE) >= 3) >= 2, ]
  if (!nrow(dds)) stop("No genes pass prefiltering for G", g)
  dds <- DESeq2::DESeq(dds, test = "Wald", quiet = TRUE)
  coefficients <- DESeq2::resultsNames(dds)
  writeLines(coefficients,
    file.path(OUTPUT_DIR, paste0("G", g, "_coefficient_names.txt")))

  for (tr in trt_order[-1L]) {
    # Coding is WT as reference genotype, Control as reference treatment.
    # This coefficient = (gsnor tr - gsnor control) -
    #                    (WT tr - WT control) in log2 fold-change units.
    target <- paste0("genotypegsnor.treatment", tr)
    if (!target %in% coefficients) {
      stop("Interaction coefficient ", target, " missing in G", g,
           "; inspect G", g, "_coefficient_names.txt.")
    }
    res <- DESeq2::results(dds, name = target, alpha = 0.05)
    out <- as_export(res)
    # WT treatment effect: treatment versus Control in the reference genotype
    wt_coefficient <- paste0("treatment_", tr, "_vs_Control")
    
    if (!wt_coefficient %in% coefficients) {
      stop("Cannot find coefficient: ", wt_coefficient,
           ". Check G", g, "_coefficient_names.txt")
    }
    
    wt_res <- DESeq2::results(
      dds, name = wt_coefficient, alpha = 0.05
    )
    
    # gsnor treatment effect = WT treatment effect + interaction
    gsnor_res <- DESeq2::results(
      dds,
      contrast = list(c(wt_coefficient, target)),
      alpha = 0.05
    )
    
    comparison <- data.frame(
      gene_id = out$gene_id,
      WT_log2FC = wt_res$log2FoldChange,
      WT_padj = wt_res$padj,
      gsnor_log2FC = gsnor_res$log2FoldChange,
      gsnor_padj = gsnor_res$padj,
      interaction_log2FC = out$log2FoldChange,
      interaction_padj = out$padj
    )
    
    comparison <- comparison[
      order(comparison$interaction_padj, na.last = TRUE),
    ]
    
    write.csv(
      comparison,
      file.path(
        OUTPUT_DIR,
        paste0("G", g, "_", tr, "_three_effects_for_gene_review.csv")
      ),
      row.names = FALSE
    )
    write.csv(out, file.path(OUTPUT_DIR, paste0("G", g, "_", tr,
      "_interaction_gsnor_minus_WT.csv")), row.names = FALSE)
    sig <- !is.na(out$padj) & out$padj < 0.05
    overview[[length(overview) + 1L]] <- data.frame(
      generation = g, treatment = tr,
      n_WT_control = as.integer(tab["WT", "Control"]),
      n_WT_treated = as.integer(tab["WT", tr]),
      n_gsnor_control = as.integer(tab["gsnor", "Control"]),
      n_gsnor_treated = as.integer(tab["gsnor", tr]),
      genes_with_testable_padj = sum(!is.na(out$padj)),
      interaction_DEGs_padj_0.05 = sum(sig),
      interaction_positive = sum(sig & out$log2FoldChange > 0),
      interaction_negative = sum(sig & out$log2FoldChange < 0)
    )
  }

  if (RUN_OMNIBUS_LRT) {
    dds_lrt <- dds
    dds_lrt <- DESeq2::DESeq(dds_lrt, test = "LRT", reduced = reduced,
                              quiet = TRUE)
    lrt <- DESeq2::results(dds_lrt, alpha = 0.05)
    write.csv(as_export(lrt), file.path(OUTPUT_DIR,
      paste0("G", g, "_any_genotype_treatment_interaction_LRT.csv")),
      row.names = FALSE)
    # The LRT p-value tests the combined contribution of all five interaction
    # terms. Its displayed log2FC is not an omnibus effect-size estimate.
  }
  message("Finished G", g)
}
write.csv(do.call(rbind, overview),
          file.path(OUTPUT_DIR, "interaction_summary_all_generations.csv"),
          row.names = FALSE)
writeLines(capture.output(sessionInfo()),
           file.path(OUTPUT_DIR, "R_sessionInfo.txt"))
message("Finished: inspect interaction coefficients and effects before revising claims.")
